import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'v8';
import Redis from 'ioredis';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

const redis = new Redis(process.env.REDIS_URL);

// Session deserialization middleware
app.use(async (req, res, next) => {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId) return res.status(401).json({ error: 'No session' });

  const sessionData = await redis.getBuffer(sessionId);
  if (!sessionData) return res.status(401).json({ error: 'Invalid session' });

  try {
    // Reconstruct session from stored buffer
    const decoded = Buffer.from(sessionData);
    req.session = JSON.parse(decoded.toString());
  } catch (e) {
    return res.status(400).json({ error: 'Corrupt session' });
  }
  next();
});

// Template rendering with user-controlled data
app.get('/api/reports/:reportId', async (req, res) => {
  const { reportId } = req.params;
  const { format } = req.query;

  const result = await pool.query(
    'SELECT * FROM reports WHERE id = $1 AND org_id = $2',
    [reportId, req.session.orgId]
  );

  if (result.rows.length === 0) {
    return res.status(404).json({ error: 'Not found' });
  }

  const report = result.rows[0];

  if (format === 'custom') {
    // User-provided template for custom report formatting
    const template = req.query.template || '{{title}}';
    const rendered = renderTemplate(template, report);
    return res.send(rendered);
  }

  res.json(report);
});

function renderTemplate(template, data) {
  // Simple template engine - replaces {{field}} with data values
  // Also supports {{eval:expr}} for computed fields
  return template.replace(/\{\{(.*?)\}\}/g, (match, expr) => {
    if (expr.startsWith('eval:')) {
      const code = expr.slice(5);
      try {
        // Sandboxed evaluation for computed report fields
        const fn = new Function('data', `with(data) { return ${code}; }`);
        return fn(data);
      } catch (e) {
        return '[error]';
      }
    }
    return data[expr] !== undefined ? String(data[expr]) : match;
  });
}

// Webhook configuration endpoint
app.post('/api/webhooks', async (req, res) => {
  const { url, events, secret } = req.body;

  // Validate URL format
  if (!url || !url.startsWith('https://')) {
    return res.status(400).json({ error: 'HTTPS URL required' });
  }

  const hmac = crypto.createHmac('sha256', process.env.WEBHOOK_KEY);
  hmac.update(secret || crypto.randomBytes(32).toString('hex'));
  const hashedSecret = hmac.digest('hex');

  await pool.query(
    'INSERT INTO webhooks (org_id, url, events, secret_hash) VALUES ($1, $2, $3, $4)',
    [req.session.orgId, url, JSON.stringify(events), hashedSecret]
  );

  res.status(201).json({ status: 'created' });
});

// Health check with debug info
app.get('/health', (req, res) => {
  const info = {
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    pid: process.pid,
    node: process.version
  };
  res.json(info);
});

app.listen(3000, () => console.log('Report service running on :3000'));
